"""
Reliability calculator: derive availability and reliability metrics
from a stream of failure and recovery events.
"""
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import List, Tuple

@dataclass
class Incident:
    failure_time: datetime
    recovery_time: datetime

@dataclass
class ReliabilityReport:
    incidents: List[Incident] = field(default_factory=list)
    window_start: datetime = field(default_factory=lambda: datetime(2024, 1, 1))
    window_end: datetime = field(default_factory=lambda: datetime(2025, 1, 1))

    def total_window_seconds(self) -> float:
        return (self.window_end - self.window_start).total_seconds()

    def total_downtime_seconds(self) -> float:
        return sum(
            (inc.recovery_time - inc.failure_time).total_seconds()
            for inc in self.incidents
        )

    def total_uptime_seconds(self) -> float:
        return self.total_window_seconds() - self.total_downtime_seconds()

    def mtbf_seconds(self) -> float:
        # Mean time between failures = uptime / number_of_failures
        if not self.incidents:
            return float("inf")
        return self.total_uptime_seconds() / len(self.incidents)

    def mttr_seconds(self) -> float:
        # Mean time to recovery = downtime / number_of_failures
        if not self.incidents:
            return 0.0
        return self.total_downtime_seconds() / len(self.incidents)

    def availability(self) -> float:
        up = self.total_uptime_seconds()
        down = self.total_downtime_seconds()
        return up / (up + down) if (up + down) > 0 else 1.0

    def nines(self) -> str:
        a = self.availability()
        if a >= 0.99999:
            return "5 nines"
        if a >= 0.9999:
            return "4 nines"
        if a >= 0.999:
            return "3 nines"
        if a >= 0.99:
            return "2 nines"
        return f"{a*100:.2f}%"

    def reliability_over(self, hours: float, failure_rate: float = None) -> float:
        # R(t) = e^(-lambda * t). Use observed failure rate if not provided.
        if failure_rate is None:
            mtbf = self.mtbf_seconds()
            if mtbf == float("inf"):
                return 1.0
            failure_rate = 1.0 / mtbf  # per second
        t = hours * 3600.0
        import math
        return math.exp(-failure_rate * t)

if __name__ == "__main__":
    start = datetime(2024, 1, 1)
    end = datetime(2024, 12, 31, 23, 59, 59)

    incidents = [
        # 4 nines target allows ~52 min downtime/year
        Incident(datetime(2024, 3, 14, 3, 0, 0), datetime(2024, 3, 14, 3, 12, 0)),
        Incident(datetime(2024, 7, 4, 14, 30, 0), datetime(2024, 7, 4, 14, 37, 0)),
        Incident(datetime(2024, 11, 23, 9, 5, 0), datetime(2024, 11, 23, 9, 9, 0)),
    ]

    report = ReliabilityReport(incidents=incidents, window_start=start, window_end=end)
    print(f"Total incidents       : {len(report.incidents)}")
    print(f"Total downtime        : {report.total_downtime_seconds()/60:.1f} min")
    print(f"MTBF                  : {report.mtbf_seconds()/3600:.1f} hours")
    print(f"MTTR                  : {report.mttr_seconds()/60:.1f} min")
    print(f"Availability          : {report.availability()*100:.5f}%")
    print(f"Nines                 : {report.nines()}")
    print(f"R(30 days)            : {report.reliability_over(30*24)*100:.4f}%")
